using CounterStrikeSharp.API.Core;
using CounterStrikeSharp.API.Core.Translations;
using CounterStrikeSharp.API.Modules.Entities.Constants;

using K4Arenas.Models;
using K4ArenaSharedApi;
using Microsoft.Extensions.Logging;

using PanoramaManager;

namespace K4Arenas;

/// <summary>
/// !guns and !rounds on one mouse-driven layout (hud/panorama/layout/custom_game/arenas_menu.xml, generated by
/// hud/tools/gen_menu.py): a Weapons tab with a row of tiles per weapon category, and a Rounds tab with a toggle per
/// round type. Replaces the KitsuneMenu center menus. The chat menus stay for a server with Hud.Menu off, or when the
/// layout failed to spawn.
///
/// <para><b>Changes apply at once</b> to the preferences in memory, which the next round reads, and reach the database
/// a moment later: one write per burst of clicks, not one per click, because the client decides how often a click
/// arrives.</para>
///
/// <para>Clicks arrive by element id and are resolved against what this viewer was shown, and checked again against the
/// config, because they come from a client.</para>
/// </summary>
public sealed class PreferencesMenu : IDisposable
{
	private const string Layout = "panorama/layout/custom_game/arenas_menu.vxml_c";

	public const int TabWeapons = 0;
	public const int TabRounds = 1;
	private const int Tabs = 2;

	// Must match hud/tools/gen_menu.py
	private const int Groups = 6;
	private const int Tiles = 16;
	private const int PerLine = 8;
	private const int RoundSlots = 16;
	private const int RoundsPerLine = 4;

	/// <summary>Seconds between the first change and the database write.</summary>
	private const float SaveDelay = 1.5f;

	/// <summary>The old menu's order, which is the enum's.</summary>
	private static readonly WeaponType[] Categories =
	[
		WeaponType.Rifle, WeaponType.Sniper, WeaponType.SMG, WeaponType.LMG, WeaponType.Shotgun, WeaponType.Pistol,
	];

	/// <summary>
	/// Tile captions. CsItem's names are not what the weapons are called (M4A1 is the M4A4, Elite the Dualies) and do
	/// not fit a 72px tile. Indexer syntax on purpose: CsItem aliases values, and Add would throw on the second name.
	/// </summary>
	private static readonly Dictionary<CsItem, string> Captions = new()
	{
		[CsItem.AK47] = "AK-47",
		[CsItem.M4A1S] = "M4A1-S",
		[CsItem.M4A1] = "M4A4",
		[CsItem.GalilAR] = "GALIL AR",
		[CsItem.Famas] = "FAMAS",
		[CsItem.SG556] = "SG 553",
		[CsItem.AUG] = "AUG",
		[CsItem.AWP] = "AWP",
		[CsItem.SSG08] = "SSG 08",
		[CsItem.SCAR20] = "SCAR-20",
		[CsItem.G3SG1] = "G3SG1",
		[CsItem.XM1014] = "XM1014",
		[CsItem.Nova] = "NOVA",
		[CsItem.MAG7] = "MAG-7",
		[CsItem.SawedOff] = "SAWED-OFF",
		[CsItem.Mac10] = "MAC-10",
		[CsItem.MP9] = "MP9",
		[CsItem.MP7] = "MP7",
		[CsItem.P90] = "P90",
		[CsItem.MP5SD] = "MP5-SD",
		[CsItem.Bizon] = "PP-BIZON",
		[CsItem.UMP45] = "UMP-45",
		[CsItem.M249] = "M249",
		[CsItem.Negev] = "NEGEV",
		[CsItem.Deagle] = "DEAGLE",
		[CsItem.Glock] = "GLOCK-18",
		[CsItem.USPS] = "USP-S",
		[CsItem.HKP2000] = "P2000",
		[CsItem.Elite] = "DUALIES",
		[CsItem.Tec9] = "TEC-9",
		[CsItem.P250] = "P250",
		[CsItem.CZ] = "CZ75-A",
		[CsItem.FiveSeven] = "FIVE-SEVEN",
		[CsItem.Revolver] = "R8",
	};

	/// <summary>The picture on a round tile whose weapon is the player's own pick of a category.</summary>
	private static readonly Dictionary<WeaponType, string> CategoryIcons = new()
	{
		[WeaponType.Rifle] = "ak47",
		[WeaponType.Sniper] = "awp",
		[WeaponType.SMG] = "mp9",
		[WeaponType.LMG] = "m249",
		[WeaponType.Shotgun] = "nova",
		[WeaponType.Pistol] = "glock",
	};

	private sealed class Viewer
	{
		public int Tab;
		public ulong SteamId;

		/// <summary>The category on each group row, and what each of its tiles stands for (null: Random).</summary>
		public readonly List<WeaponType> Groups = [];
		public readonly List<List<CsItem?>> Options = [];

		/// <summary>The round type id on each round tile.</summary>
		public readonly List<int> Rounds = [];

		/// <summary>The i- class on each tile, so the next one can take it off: two at once draw whichever the
		/// stylesheet lists last.</summary>
		public readonly Dictionary<string, string> Icons = [];

		public bool Warned;
	}

	private readonly Plugin _plugin;
	private readonly PanelHandle _panel;
	private readonly Dictionary<int, Viewer> _viewers = [];
	private readonly HashSet<ulong> _pendingSaves = [];

	private PreferencesMenu(Plugin plugin)
	{
		_plugin = plugin;
		_panel = Panorama.Spawn(Layout, new LayoutContract
		{
			// Unique server-wide: dialog variables are keyed by panel id
			RootPanelId = "ArenasMenuRoot",
			RevealClass = "show",
			CloseButtonId = "am_close",
			RowCount = 0,
			CaptureInput = true,
			HideHud = HideHudFlags.None,
			SharedText = false,
		});
		_panel.OnEvent += OnEvent;
	}

	/// <summary>Spawns the layout once. Null when it cannot: the commands then open the chat menus.</summary>
	public static PreferencesMenu? TryCreate(Plugin plugin)
	{
		try
		{
			Panorama.Init(plugin);
			var menu = new PreferencesMenu(plugin);
			plugin.Logger.LogInformation("[Hud] Arena preferences menu ready");
			return menu;
		}
		catch (Exception ex)
		{
			plugin.Logger.LogWarning("[Hud] Arena preferences menu failed to start, using the chat menus: {Message}", ex.Message);
			return null;
		}
	}

	public void Dispose()
	{
		_panel.Dispose();
		_viewers.Clear();
	}

	/// <summary>
	/// !guns (Weapons) or !rounds (Rounds). The same command again closes it, since there is no Escape key; the other
	/// one switches tab. False when the menu cannot show this player any text, so the caller opens the chat menu.
	/// </summary>
	public bool Open(CCSPlayerController player, int tab)
	{
		if (player is not { IsValid: true, IsBot: false, IsHLTV: false })
			return false;

		// Every word on the card is a per-viewer variable. Without that the card draws empty.
		if (!Panorama.CanWritePerPlayerText)
			return false;

		var arena = _plugin.Arenas?.FindPlayer(player);
		if (arena == null)
			return true;

		tab = Math.Clamp(tab, 0, Tabs - 1);

		if (_panel.IsOpenFor(player) && _viewers.TryGetValue(player.Slot, out var open))
		{
			if (open.Tab == tab)
			{
				_panel.Close(player);
				return true;
			}

			open.Tab = tab;
			DrawTabs(player, open);
			return true;
		}

		_panel.Open(player);
		if (!_panel.IsOpenFor(player))
			return false;

		// Open took every per-viewer class off, so nothing is on any tile yet
		var viewer = _viewers[player.Slot] = new Viewer { Tab = tab, SteamId = player.SteamID };
		DrawAll(player, viewer, arena, force: false);
		return true;
	}

	public void Forget(int slot)
	{
		_panel.Close(slot);
		_viewers.Remove(slot);
	}

	// ------------------------------------------------------------------ drawing

	private void DrawAll(CCSPlayerController player, Viewer viewer, ArenaPlayer arena, bool force)
	{
		Set(player, "am_title", Lang(player, "k4.menu.title", "Arena"));
		Set(player, "am_tag", Lang(player, "k4.menu.tag", "Preferences"));
		Set(player, "am_tab0", Lang(player, "k4.menu.tab.weapons", "Weapons"));
		Set(player, "am_tab1", Lang(player, "k4.menu.tab.rounds", "Rounds"));
		Set(player, "am_done", Lang(player, "k4.menu.done", "Done"));
		Set(player, "am_r_intro", Lang(player, "k4.menu.rounds_intro",
			"The round types you play. Each round is one that you and your opponent both have on."));
		Hint(player, viewer, warn: false);

		DrawTabs(player, viewer);
		DrawWeapons(player, viewer, arena, force);
		DrawRounds(player, viewer, arena, force);
	}

	private void DrawTabs(CCSPlayerController player, Viewer viewer)
	{
		for (var i = 0; i < Tabs; i++)
		{
			Cls(player, $"am_tab{i}", "active", i == viewer.Tab);
			Cls(player, $"am_pg{i}", "active", i == viewer.Tab);
			Cls(player, "am_bar", $"at-{i}", i == viewer.Tab);
		}
	}

	private void Hint(CCSPlayerController player, Viewer viewer, bool warn)
	{
		Set(player, "am_hint", warn
			? Lang(player, "k4.menu.hint_last_round", "Keep at least one round type on.")
			: Lang(player, "k4.menu.hint", "Changes count from your next round."));
		Cls(player, "am_hint", "warn", warn);
		viewer.Warned = warn;
	}

	private void DrawWeapons(CCSPlayerController player, Viewer viewer, ArenaPlayer arena, bool force)
	{
		viewer.Groups.Clear();
		viewer.Options.Clear();

		var shown = Categories.Where(arena.IsAllowedWeaponType).Take(Groups).ToList();

		for (var g = 0; g < Groups; g++)
		{
			var id = $"am_g{g}";

			if (g >= shown.Count)
			{
				Cls(player, id, "hidden", true);
				continue;
			}

			var type = shown[g];
			var options = new List<CsItem?> { null };
			options.AddRange(WeaponModel.GetWeaponList(type)
				.Where(item => WeaponModel.GetWeaponType(item) == type)
				.Distinct()
				.Select(item => (CsItem?)item));

			if (options.Count > Tiles)
				options.RemoveRange(Tiles, options.Count - Tiles);

			viewer.Groups.Add(type);
			viewer.Options.Add(options);

			Set(player, $"{id}_k", Lang(player, $"k4.rounds.{type.ToString().ToLowerInvariant()}", type.ToString()));
			Cls(player, $"{id}_l1", "hidden", options.Count <= PerLine);

			for (var t = 0; t < Tiles; t++)
			{
				var tile = $"{id}_w{t}";

				if (t >= options.Count)
				{
					Cls(player, tile, "hidden", true);
					continue;
				}

				var item = options[t];
				Set(player, tile, item is { } weapon ? Caption(weapon) : RandomText(player));
				Icon(player, viewer, tile, item is { } shownWeapon ? HudService.IconOf(shownWeapon) : "random", force);
				Cls(player, tile, "hidden", false);
			}

			DrawPick(player, viewer, g, arena);
			Cls(player, id, "hidden", false);
		}
	}

	/// <summary>The current pick of one category: the gold tile and the name under the category.</summary>
	private void DrawPick(CCSPlayerController player, Viewer viewer, int group, ArenaPlayer arena)
	{
		var id = $"am_g{group}";
		var current = arena.WeaponPreferences.GetValueOrDefault(viewer.Groups[group]);
		var options = viewer.Options[group];

		Set(player, $"{id}_v", current is { } weapon ? Caption(weapon) : RandomText(player));

		for (var t = 0; t < options.Count; t++)
			Cls(player, $"{id}_w{t}", "sel", options[t] == current);
	}

	private void DrawRounds(CCSPlayerController player, Viewer viewer, ArenaPlayer arena, bool force)
	{
		viewer.Rounds.Clear();

		var rounds = RoundType.RoundTypes.Take(RoundSlots).ToList();

		for (var r = 0; r < RoundSlots; r++)
		{
			var id = $"am_r{r}";

			if (r >= rounds.Count)
			{
				Cls(player, id, "hidden", true);
				continue;
			}

			var round = rounds[r];
			viewer.Rounds.Add(round.ID);

			var chip = IsHeadshotRound(round) ? Lang(player, "k4.hud.chip.hs", "HS") : string.Empty;
			Set(player, id, RoundName(player, round));
			Set(player, $"{id}_c", chip);
			Cls(player, id, "has-chip", chip.Length > 0);
			Icon(player, viewer, id, RoundIcon(round), force);
			DrawRoundState(player, r, arena.RoundPreferences.Any(p => p.ID == round.ID));
			Cls(player, id, "hidden", false);
		}

		for (var line = 0; line < RoundSlots / RoundsPerLine; line++)
			Cls(player, $"am_rl{line}", "hidden", line * RoundsPerLine >= rounds.Count);
	}

	private void DrawRoundState(CCSPlayerController player, int tile, bool on)
	{
		Set(player, $"am_r{tile}_s", on ? Lang(player, "k4.menu.on", "On") : Lang(player, "k4.menu.off", "Off"));
		Cls(player, $"am_r{tile}", "on", on);
	}

	/// <summary>
	/// Exactly one i- class on a tile. Forced after the library rebuilt the panel: a round restart keeps the classes
	/// the entity wore and a map change drops them, so the recorded one is written again either way.
	/// </summary>
	private void Icon(CCSPlayerController player, Viewer viewer, string tile, string slug, bool force)
	{
		var wanted = "i-" + slug;

		if (viewer.Icons.TryGetValue(tile, out var old))
		{
			if (old == wanted && !force)
				return;

			if (old != wanted)
				Cls(player, tile, old, false);
		}

		Cls(player, tile, wanted, true);
		viewer.Icons[tile] = wanted;
	}

	// ------------------------------------------------------------------ input

	private void OnEvent(PanelEvent e)
	{
		if (e.Player is not { IsValid: true } player)
			return;

		switch (e.Action)
		{
			case PanelAction.Close:
				_viewers.Remove(player.Slot);
				return;

			case PanelAction.Restored:
			{
				var arena = _plugin.Arenas?.FindPlayer(player);

				if (!_viewers.TryGetValue(player.Slot, out var restored) || arena == null || arena.SteamID != restored.SteamId)
				{
					_panel.Close(player);
					return;
				}

				DrawAll(player, restored, arena, force: true);
				return;
			}

			case PanelAction.Button:
				if (_viewers.TryGetValue(player.Slot, out var viewer))
					Click(player, viewer, e.ElementId);
				return;
		}
	}

	private void Click(CCSPlayerController player, Viewer viewer, string id)
	{
		if (id == "am_done")
		{
			_panel.Close(player);
			return;
		}

		if (id.StartsWith("am_tab", StringComparison.Ordinal) && int.TryParse(id.AsSpan(6), out var tab) && tab is >= 0 and < Tabs)
		{
			viewer.Tab = tab;
			DrawTabs(player, viewer);
			return;
		}

		// The arena player is rebuilt on reconnect; the menu belongs to the one it was opened for
		var arena = _plugin.Arenas?.FindPlayer(player);
		if (arena == null || arena.SteamID != viewer.SteamId)
		{
			_panel.Close(player);
			return;
		}

		if (TryParseTile(id, out var group, out var tile))
		{
			PickWeapon(player, viewer, arena, group, tile);
			return;
		}

		if (id.StartsWith("am_r", StringComparison.Ordinal) && int.TryParse(id.AsSpan(4), out var round))
			ToggleRound(player, viewer, arena, round);
	}

	private void PickWeapon(CCSPlayerController player, Viewer viewer, ArenaPlayer arena, int group, int tile)
	{
		if (group < 0 || group >= viewer.Groups.Count || tile < 0 || tile >= viewer.Options[group].Count)
			return;

		var type = viewer.Groups[group];

		// The config may have turned the category off since the draw
		if (!arena.IsAllowedWeaponType(type))
		{
			DrawWeapons(player, viewer, arena, force: false);
			return;
		}

		var item = viewer.Options[group][tile];
		if (arena.WeaponPreferences.GetValueOrDefault(type) == item)
			return;

		arena.WeaponPreferences[type] = item;
		DrawPick(player, viewer, group, arena);

		if (viewer.Warned)
			Hint(player, viewer, warn: false);

		QueueSave(arena);
	}

	private void ToggleRound(CCSPlayerController player, Viewer viewer, ArenaPlayer arena, int tile)
	{
		if (tile < 0 || tile >= viewer.Rounds.Count)
			return;

		var id = viewer.Rounds[tile];
		var index = RoundType.RoundTypes.FindIndex(r => r.ID == id);

		// A special round plugin unloaded since the draw
		if (index < 0)
		{
			DrawRounds(player, viewer, arena, force: false);
			return;
		}

		var on = arena.RoundPreferences.Any(r => r.ID == id);

		if (!arena.SetRoundPreference(RoundType.RoundTypes[index], !on))
		{
			Hint(player, viewer, warn: true);
			return;
		}

		DrawRoundState(player, tile, !on);

		if (viewer.Warned)
			Hint(player, viewer, warn: false);

		QueueSave(arena);
	}

	/// <summary>One database write per player per burst of clicks. Not stopped on a map change: the change is made.</summary>
	private void QueueSave(ArenaPlayer arena)
	{
		if (!_pendingSaves.Add(arena.SteamID))
			return;

		_plugin.AddTimer(SaveDelay, () =>
		{
			_pendingSaves.Remove(arena.SteamID);

			Task.Run(async () =>
			{
				try
				{
					await arena.SavePlayerPreferencesAsync();
				}
				catch (Exception)
				{
					// SavePlayerPreferencesAsync logs it; the preferences stay in memory for this session
				}
			});
		});
	}

	private static bool TryParseTile(string id, out int group, out int tile)
	{
		group = tile = -1;

		if (!id.StartsWith("am_g", StringComparison.Ordinal))
			return false;

		var split = id.IndexOf("_w", 4, StringComparison.Ordinal);

		return split > 4
			&& int.TryParse(id.AsSpan(4, split - 4), out group)
			&& int.TryParse(id.AsSpan(split + 2), out tile);
	}

	// ------------------------------------------------------------------ rounds

	private string RoundName(CCSPlayerController player, RoundType round)
	{
		var name = round.Name ?? string.Empty;

		var own = Lang(player, $"k4.menu.round.{name}", string.Empty);
		if (own.Length > 0)
			return own;

		if (round.StartFunction != null && HudService.SpecialRounds.TryGetValue(name, out var special))
		{
			// The banner's title without its last word: "One tap round" -> "One tap"
			var title = Lang(player, $"k4.hud.round.{name}", special.Title);
			return title.EndsWith(" round", StringComparison.OrdinalIgnoreCase) ? title[..^6] : title;
		}

		return Lang(player, name, name);
	}

	private static bool IsHeadshotRound(RoundType round) =>
		round.StartFunction != null && HudService.SpecialRounds.TryGetValue(round.Name ?? string.Empty, out var special) && special.Headshots;

	/// <summary>What the round hands out, like the banner's guess; "none" collapses the picture (2vs2, 3vs3, random).</summary>
	private static string RoundIcon(RoundType round)
	{
		if (round.StartFunction != null)
			return HudService.SpecialRounds.GetValueOrDefault(round.Name ?? string.Empty)?.Weapon ?? "none";

		if (round.PrimaryPreference == WeaponType.Unknown)
			return "none";

		if (round.PrimaryWeapon is { } primary)
			return HudService.IconOf(primary);

		if (round.UsePreferredPrimary && round.PrimaryPreference is { } type)
			return CategoryIcons.GetValueOrDefault(type, "none");

		if (round.SecondaryWeapon is { } secondary)
			return HudService.IconOf(secondary);

		if (round.UsePreferredSecondary)
			return CategoryIcons[WeaponType.Pistol];

		return "knife";
	}

	// ------------------------------------------------------------------ text

	private static string Caption(CsItem item) =>
		Captions.TryGetValue(item, out var caption) ? caption : item.ToString().ToUpperInvariant();

	private string RandomText(CCSPlayerController player) => Lang(player, "k4.general.random", "Random");

	/// <summary>A phrase from lang/ in the player's language, or the fallback when the lang file does not have it.
	/// Chat color codes come out: a Label would draw them as boxes.</summary>
	private string Lang(CCSPlayerController player, string key, string fallback)
	{
		var text = _plugin.Localizer.ForPlayer(player, key);

		if (string.IsNullOrEmpty(text) || text == key)
			return fallback;

		return text.Any(char.IsControl) ? new string(text.Where(c => !char.IsControl(c)).ToArray()) : text;
	}

	private void Set(CCSPlayerController player, string name, string value) => _panel.SetVariableFor(player, name, value);

	private void Cls(CCSPlayerController player, string id, string cls, bool on) => _panel.SetClassFor(player, id, cls, on);
}
